import React from "react";

const destinations = [
  {
    name: "Historic Temple",
    description: "A serene ancient temple known for its peaceful vibes and stunning architecture.",
    bestTime: "Morning (6 AM - 10 AM)",
    safety: "Safe",
  },
  {
    name: "Riverfront Ghat",
    description: "Perfect place to witness sunrise, enjoy local food, and connect with nature.",
    bestTime: "Sunrise or Sunset",
    safety: "Moderate (crowded during festivals)",
  },
  {
    name: "Local Bazaar",
    description: "Explore vibrant handicrafts, souvenirs, and street food in this colorful market.",
    bestTime: "Afternoon (12 PM - 4 PM)",
    safety: "Caution (pickpocket-prone areas)",
  },
  {
    name: "Cultural Museum",
    description: "Discover history, heritage, and art that narrates the city’s glorious past.",
    bestTime: "Anytime between 10 AM - 6 PM",
    safety: "Safe",
  },
  {
    name: "Sunset Point",
    description: "A mesmerizing hilltop spot offering panoramic views of the city skyline.",
    bestTime: "Evening (5 PM - 7 PM)",
    safety: "Safe",
  },
];

export default function RoutePlanner({ tourist, onProceed }) {
  return (
    <div
      style={{
        background: "linear-gradient(135deg, #FFB75E, #ED8F03)",
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: "40px",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.95)",
          borderRadius: "20px",
          padding: "30px",
          boxShadow: "0 8px 20px rgba(0, 0, 0, 0.2)",
          width: "90%",
          maxWidth: "700px",
          textAlign: "center",
        }}
      >
        <h1 style={{ color: "#A0522D", marginBottom: "10px" }}>🌍 My Journey</h1>
        <p style={{ fontSize: "1.1rem", color: "#333", marginBottom: "25px" }}>
          Welcome, <strong>{tourist.name}</strong>! Here are some amazing places you can explore during your journey.
        </p>

        <div
          style={{
            maxHeight: "400px",
            overflowY: "auto",
            paddingRight: "10px",
            textAlign: "left",
          }}
        >
          {destinations.map((dest, index) => (
            <div
              key={index}
              style={{
                backgroundColor: "rgba(255, 255, 255, 0.9)",
                borderRadius: "15px",
                padding: "15px 20px",
                marginBottom: "15px",
                boxShadow: "0 4px 10px rgba(0, 0, 0, 0.1)",
              }}
            >
              <h3 style={{ color: "#D2691E", marginBottom: "5px" }}>📍 {dest.name}</h3>
              <p style={{ marginBottom: "5px" }}>{dest.description}</p>
              <p style={{ margin: "3px 0" }}>
                <strong>🕐 Best Time:</strong> {dest.bestTime}
              </p>
              <p style={{ margin: "3px 0" }}>
                <strong>🔒 Safety:</strong> {dest.safety}
              </p>
            </div>
          ))}
        </div>

        <button
          onClick={onProceed}
          style={{
            marginTop: "25px",
            backgroundColor: "#FF7A00",
            border: "none",
            color: "white",
            padding: "12px 24px",
            borderRadius: "10px",
            fontSize: "1rem",
            cursor: "pointer",
            boxShadow: "0 4px 10px rgba(0, 0, 0, 0.2)",
            transition: "transform 0.2s ease, background 0.3s ease",
          }}
          onMouseOver={(e) => (e.target.style.backgroundColor = "#e56f00")}
          onMouseOut={(e) => (e.target.style.backgroundColor = "#FF7A00")}
        >
          🚶‍♂️ Start My Journey
        </button>
      </div>
    </div>
  );
}
